def scene_tools(p="at"):
    """한지 위에 붓으로 쓴 지방·축문과 벼루."""
    lines = "".join(f'<rect x="{x}" y="{y0}" width="9" height="{h}" rx="3" fill="#2b2622" opacity=".82"/>'
                    for x, y0, h in ((612, 120, 210), (582, 120, 170), (552, 120, 190), (522, 120, 150), (492, 120, 200)))
    return (f'<defs><linearGradient id="{p}s" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f4e8dc"/><stop offset="1" stop-color="#e8d3bf"/></linearGradient></defs>'
            f'<rect width="1200" height="500" fill="url(#{p}s)"/>'
            '<rect x="0" y="400" width="1200" height="100" fill="#7a3b2e"/><rect x="0" y="396" width="1200" height="8" fill="#5e2c22"/>'
            '<rect x="440" y="80" width="240" height="320" fill="#fbf7ee" stroke="#e0d2bd" stroke-width="2"/>' + lines +
            '<rect x="700" y="130" width="70" height="250" fill="#fbf7ee" stroke="#e0d2bd" stroke-width="2"/>'
            '<rect x="729" y="150" width="9" height="200" rx="3" fill="#2b2622" opacity=".82"/>'
            '<rect x="330" y="310" width="90" height="90" rx="10" fill="#3a3330"/><ellipse cx="375" cy="345" rx="30" ry="22" fill="#151211"/>'
            '<g transform="rotate(-28 860 260)"><rect x="850" y="120" width="16" height="230" rx="6" fill="#a8774f"/><rect x="848" y="110" width="20" height="14" rx="3" fill="#5e2c22"/>'
            '<path d="M850 350 C852 380 858 400 858 412 C858 400 864 380 866 350Z" fill="#2b2622"/></g>'
            '<circle cx="1000" cy="150" r="60" fill="#c0392b" opacity=".12"/><rect x="960" y="300" width="80" height="80" rx="6" fill="#c0392b" opacity=".85"/>'
            '<path d="M976 318 h48 M976 340 h48 M976 362 h48 M1000 318 v44" stroke="#fbe9e4" stroke-width="5"/>')


